// Intake simulation: in production this is a folder watch
// or an email-inbox trigger. Here it emits a realistic batch —
// including the dirty rows every real intake has.
return [
  { json: { invoice_no: 'INV-1001', pdf_file: 'INV-1001.pdf', customer_key: 'acme' } },
  { json: { invoice_no: 'INV-1002', pdf_file: 'INV-1002.pdf', customer_key: 'globex' } },
  { json: { invoice_no: 'INV-1003', pdf_file: 'INV-1003.pdf', customer_key: 'unknown_co' } },
  { json: { invoice_no: 'INV-1001', pdf_file: 'INV-1001.pdf', customer_key: 'acme' } }
];

// Customer lookup + dedup. DEMO MODE: customer table is inline.
// In production: replace `customers` with a Sheet/DB read before this node.
const customers = {
  acme:   { name: 'Acme Facilities', email: 'billing@acme.example' },
  globex: { name: 'Globex Corp',     email: 'ap@globex.example' }
};
const seen = new Set();
return $input.all().map(({ json: d }) => {
  const c = customers[d.customer_key];
  const dup = seen.has(d.invoice_no);
  if (!dup && c) seen.add(d.invoice_no);
  return { json: {
    ...d,
    customer_name: c ? c.name : null,
    customer_email: c ? c.email : null,
    duplicate: dup,
    sendable: !!c && !dup
  }};
});

// Compose the invoice email.
// DEMO MODE: composes the payload only. To go live, add a
// 'Send Email' or 'Gmail' node after this one and map
// to/subject/body/attachment — the shape is already correct.
const d = $json;
return {
  json: {
    status: 'composed',
    to: d.customer_email,
    subject: `Invoice ${d.invoice_no} — ${d.customer_name}`,
    body: `Hi ${d.customer_name},\n\nPlease find invoice ${d.invoice_no} attached.\n\nThanks,\nBilling`,
    attachment: d.pdf_file
  }
};

// Alert the owner — the failure path is a first-class output,
// not a dropped row.
const d = $json;
const reason = d.duplicate
  ? `duplicate of ${d.invoice_no} — already processed`
  : `no customer record for key '${d.customer_key}'`;
return {
  json: {
    status: 'alerted',
    channel: 'owner-alert',
    alert: `Invoice ${d.invoice_no} NOT sent: ${reason}`
  }
};

// Aggregate the run into one owner-digest item.
// Both branches feed this node — items arrive tagged by status.
const items = $input.all();
const sent = items.filter(i => i.json.status === 'composed');
const alerts = items.filter(i => i.json.status === 'alerted');
const lines = alerts.map(i => '  - ' + i.json.alert);
return {
  json: {
    status: 'digest',
    channel: 'owner-digest',
    summary: `Run complete: ${sent.length} invoice(s) composed, ${alerts.length} alert(s)`,
    needs_attention: alerts.map(i => i.json.alert),
    detail: lines.join('\n') || '  (nothing needs attention)'
  }
};
